const questions=[{id:'hello',topic:'travel',q:'You enter a shop. What do you say first?',a:['Bonjour !','Au revoir !','L’addition !'],correct:0,why:'A simple bonjour before a request is an essential French courtesy.'},{id:'station',topic:'travel',q:'Ask where the train station is.',a:['J’ai une réservation.','Où est la gare ?','Une table, s’il vous plaît.'],correct:1,why:'Où est… ? means “Where is…?” La gare is the train station.'},{id:'right',topic:'travel',q:'You hear “C’est à droite.” Which direction?',a:['Straight ahead','Left','Right'],correct:2,why:'À droite = right. À gauche = left. Tout droit = straight ahead.'},{id:'ticket',topic:'travel',q:'Politely ask for a ticket to Angers.',a:['Je voudrais un billet pour Angers.','Je suis Angers.','Je voudrais une table.'],correct:0,why:'Je voudrais… is a polite, useful way to say “I would like…”'},{id:'coffee',topic:'food',q:'Order a coffee politely.',a:['Où est le café ?','Un café, s’il vous plaît.','Je m’appelle café.'],correct:1,why:'Un café usually means an espresso in France. Add s’il vous plaît for “please”.'},{id:'here',topic:'food',q:'The server asks “Sur place ou à emporter ?” You want to sit down.',a:['À emporter.','L’addition.','Sur place, merci.'],correct:2,why:'Sur place = for here. À emporter = to take away.'},{id:'bill',topic:'food',q:'You have finished your meal. Ask for the bill.',a:['L’addition, s’il vous plaît.','Bonjour, je suis Alex.','Un billet, s’il vous plaît.'],correct:0,why:'L’addition is the restaurant bill. You usually ask for it when ready.'},{id:'water',topic:'food',q:'How do you ask for a jug of tap water?',a:['Une salle de conférence.','Une carafe d’eau, s’il vous plaît.','Une réservation.'],correct:1,why:'Une carafe d’eau is a jug of tap water, commonly requested with meals.'},{id:'name',topic:'conference',q:'Introduce yourself to another attendee.',a:['Je voudrais Alex.','Où est Alex ?','Je m’appelle Alex.'],correct:2,why:'Je m’appelle… means “My name is…” Replace Alex with your own name.'},{id:'repeat',topic:'conference',q:'Someone speaks too quickly. What helps?',a:['Pouvez-vous répéter plus lentement ?','Au revoir !','L’addition, s’il vous plaît.'],correct:0,why:'This asks them to repeat more slowly. It is useful in every scenario.'},{id:'talk',topic:'conference',q:'Compliment a speaker’s presentation.',a:['Je voudrais un café.','Votre présentation était très intéressante.','Où est la gare ?'],correct:1,why:'Votre is the polite “your”. Intéressante agrees with présentation.'},{id:'english',topic:'conference',q:'Ask whether someone speaks English.',a:['Je parle anglais.','Je m’appelle anglais.','Vous parlez anglais ?'],correct:2,why:'Vous parlez anglais ? is a natural spoken question. Vous is polite.'}];
questions.push(
  {id:'hotel-booking',topic:'hotel',q:'Tell the receptionist your booking is in the name of Martin.',a:['Une réservation au nom de Martin.','Je voudrais une gare.','La carte, s’il vous plaît.'],correct:0,why:'Une réservation au nom de… means “a reservation in the name of…”. Use your own surname.'},
  {id:'hotel-breakfast',topic:'hotel',q:'Ask what time breakfast is served.',a:['Quel est votre nom ?','À quelle heure est le petit-déjeuner ?','Où est la gare ?'],correct:1,why:'À quelle heure… ? asks “At what time…?” Le petit-déjeuner is breakfast.'},
  {id:'hotel-wifi',topic:'hotel',q:'Ask for the Wi-Fi password.',a:['Je peux payer par carte ?','Je viens chercher mon badge.','Quel est le mot de passe du Wi-Fi ?'],correct:2,why:'Le mot de passe means “the password”. Wi-Fi is commonly pronounced “wee-fee” in French.'},
  {id:'hotel-checkout',topic:'hotel',q:'Ask when you must leave your hotel room.',a:['À quelle heure faut-il quitter la chambre ?','À quelle heure part le tram ?','Je travaille dans la recherche.'],correct:0,why:'Quitter la chambre means to leave the room. Faut-il… ? asks what is required.'},
  {id:'tram-stop',topic:'tram',q:'Ask someone where the tram stop is.',a:['Où est la carte ?','Où est l’arrêt de tram ?','Où est mon badge ?'],correct:1,why:'Un arrêt is a stop. L’arrêt de tram is the tram stop; la gare is the train station.'},
  {id:'tram-line',topic:'tram',q:'Ask which tram line you should take.',a:['Vous avez un plat végétarien ?','Quel est votre nom ?','Quelle ligne dois-je prendre ?'],correct:2,why:'Quelle ligne… ? asks “Which line…?” Prendre le tram means to take the tram.'},
  {id:'tram-time',topic:'tram',q:'Ask when the next tram leaves.',a:['À quelle heure part le prochain tram ?','À quelle heure est le petit-déjeuner ?','Combien ça coûte ?'],correct:0,why:'Le prochain tram is the next tram. Part comes from partir, “to leave”.'},
  {id:'tram-validate',topic:'tram',q:'You are unsure how to validate your ticket. Ask for help.',a:['Je voudrais le programme.','Comment valider mon billet ?','Je peux avoir la carte ?'],correct:1,why:'Comment… ? means “How…?” Valider mon billet means to validate my ticket. Follow local ticket instructions.'},
  {id:'bakery-bread',topic:'bakery',q:'Order a baguette politely.',a:['Une table pour une personne.','Un billet pour Angers.','Une baguette, s’il vous plaît.'],correct:2,why:'Une baguette is a long loaf of bread. Use une because baguette is feminine.'},
  {id:'bakery-quantity',topic:'bakery',q:'Ask for two croissants.',a:['Deux croissants, s’il vous plaît.','Un croissant, s’il vous plaît.','Une carafe d’eau, s’il vous plaît.'],correct:0,why:'Deux means “two”. The final s in croissants is not pronounced.'},
  {id:'bakery-price',topic:'bakery',q:'Ask how much something costs.',a:['Comment vous appelez-vous ?','Combien ça coûte ?','Où est la salle ?'],correct:1,why:'Combien ça coûte ? is the everyday question “How much does it cost?”'},
  {id:'bakery-card',topic:'bakery',q:'Ask if you can pay by card.',a:['Je peux vous poser une question ?','Je peux avoir le programme ?','Je peux payer par carte ?'],correct:2,why:'Payer par carte means “to pay by card”. Je peux… ? is a natural spoken way to ask permission.'},
  {id:'restaurant-menu',topic:'restaurant',q:'Ask to see the restaurant’s full menu.',a:['Je peux avoir la carte, s’il vous plaît ?','Je peux avoir mon badge ?','Je voudrais un billet.'],correct:0,why:'La carte lists the dishes. Un menu usually means a fixed-price set meal in France.'},
  {id:'restaurant-vegetarian',topic:'restaurant',q:'Ask whether there is a vegetarian dish.',a:['Vous parlez anglais ?','Vous avez un plat végétarien ?','Vous avez une réservation ?'],correct:1,why:'Un plat is a dish or main course. Végétarien describes a masculine noun such as plat.'},
  {id:'restaurant-allergy',topic:'restaurant',q:'Tell the server you are allergic to peanuts.',a:['Je voudrais des arachides.','Je travaille dans la recherche.','Je suis allergique aux arachides.'],correct:2,why:'Je suis allergique à… states an allergy. Aux is à + les. Arachides means peanuts; cacahuètes is also common.'},
  {id:'restaurant-finished',topic:'restaurant',q:'The server asks if you have finished. Reply politely.',a:['J’ai terminé, merci.','Je viens chercher mon badge.','Sur place, merci.'],correct:0,why:'J’ai terminé means “I have finished”. It lets the server know they may clear your plate.'},
  {id:'registration-badge',topic:'registration',q:'Tell the conference desk you are here to collect your badge.',a:['Je voudrais une baguette.','Je viens chercher mon badge.','Je peux payer par carte ?'],correct:1,why:'Je viens chercher… means “I’m here to collect…” or “I’ve come to collect…”.'},
  {id:'registration-programme',topic:'registration',q:'Ask for the conference programme.',a:['Je peux avoir la carte ?','Je peux avoir l’addition ?','Je peux avoir le programme ?'],correct:2,why:'Le programme lists sessions and times. Je peux avoir… ? means “May I have…?”'},
  {id:'registration-room',topic:'registration',q:'Ask where the conference room is.',a:['Où est la salle de conférence ?','Où est l’arrêt de tram ?','Où est la chambre ?'],correct:0,why:'La salle de conférence is the conference room. Une chambre is usually a bedroom.'},
  {id:'registration-start',topic:'registration',q:'Ask what time the session starts.',a:['À quelle heure faut-il quitter la chambre ?','À quelle heure commence la séance ?','À quelle heure part le train ?'],correct:1,why:'La séance is a session. Commence means “starts”.'},
  {id:'networking-field',topic:'networking',q:'Say that you work in research.',a:['Je viens chercher mon badge.','Je voudrais une réservation.','Je travaille dans la recherche.'],correct:2,why:'Je travaille dans… means “I work in…”. La recherche means research.'},
  {id:'networking-question',topic:'networking',q:'Politely ask a speaker if you may ask a question.',a:['Je peux vous poser une question ?','Vous avez un plat végétarien ?','Je peux payer par carte ?'],correct:0,why:'Poser une question means “to ask a question”. Vous keeps the request polite.'},
  {id:'networking-contact',topic:'networking',q:'Suggest exchanging email addresses.',a:['On peut changer de table ?','On peut échanger nos adresses e-mail ?','On peut avoir une carafe d’eau ?'],correct:1,why:'On peut… ? means “Can we…?” Échanger means to exchange, and nos means “our”.'},
  {id:'networking-thanks',topic:'networking',q:'Thank someone for taking the time to talk.',a:['Merci pour le billet.','Merci pour le café.','Merci pour votre temps.'],correct:2,why:'Merci pour… means “Thank you for…”. Votre temps means “your time” in a polite form.'}
);
// Restore only the supported progress shape; malformed or old storage must not block lessons.
function restoreProgress() {
  const clean = {xp:0, answers:{}, days:[], complete:[], day:1};
  const count = n => Number.isSafeInteger(n) && n >= 0 ? n : 0;
  try {
    const saved = JSON.parse(localStorage.getItem('bonjour-angers-v1'));
    if (!saved || typeof saved !== 'object') return clean;
    clean.xp = count(saved.xp);
    clean.day = Number.isInteger(saved.day) && saved.day >= 1 && saved.day <= 7 ? saved.day : 1;
    clean.days = Array.isArray(saved.days) ? [...new Set(saved.days.filter(d => typeof d === 'string' && d.length <= 20))] : [];
    clean.complete = Array.isArray(saved.complete) ? saved.complete.filter(id => topics.some(t => t.id === id)) : [];
    if (saved.answers && typeof saved.answers === 'object' && !Array.isArray(saved.answers)) {
      for (const q of questions) {
        const a = saved.answers[q.id];
        if (a && typeof a === 'object') clean.answers[q.id] = {
          right:count(a.right), miss:count(a.miss), attempts:Math.max(count(a.attempts),count(a.right)+count(a.miss)),
          streak: Math.min(2, a.streak === undefined ? Math.max(0,count(a.right)-count(a.miss)) : count(a.streak))
        };
      }
    }
  } catch {}
  return clean;
}
let state = restoreProgress();
let view='vocabulary',filter='all',session=[],qi=0,answered=false,sessionCorrect=0;const app=document.querySelector('#app'),modal=document.querySelector('#lesson'),content=document.querySelector('#lessonContent');
function save(){try{localStorage.setItem('bonjour-angers-v1',JSON.stringify(state))}catch{document.querySelector('#saved').textContent='Storage unavailable — session only';document.querySelector('.save-status').dataset.error='true'}}
function toast(s){let t=document.querySelector('#toast');t.textContent=s;t.style.display='block';setTimeout(()=>t.style.display='none',3500)}
function speak(text,slow=false){
  if(!('speechSynthesis' in window)){toast('Audio unavailable on this device.');return Promise.resolve(false);}
  return new Promise(resolve=>{
    speechSynthesis.cancel();
    const utterance=new SpeechSynthesisUtterance(text);utterance.lang='fr-FR';utterance.rate=slow?.65:.9;
    const voice=speechSynthesis.getVoices().find(v=>v.lang.startsWith('fr'));if(voice)utterance.voice=voice;
    let settled=false;const finish=ok=>{if(settled)return;settled=true;clearTimeout(timer);resolve(ok);};
    const timer=setTimeout(()=>{toast('Audio did not start. Try again or skip.');finish(false);},7000);
    utterance.onstart=()=>finish(true);utterance.onerror=event=>{if(settled)return;if(!['canceled','interrupted'].includes(event.error))toast('Audio unavailable. Try again or skip.');finish(false);};
    try{speechSynthesis.speak(utterance);}catch{finish(false);}
  });
}
function audio(text,slow=false){const b=document.createElement('button');b.className='secondary';b.textContent=slow?'◷ Slow':'▶ Listen';b.setAttribute('aria-label',(slow?'Listen slowly: ':'Listen: ')+text);b.onclick=()=>speak(text,slow);return b}
function stats(){let mastered=Object.values(state.answers).filter(x=>x.right>=2).length;return `<div class="stats"><div class="stat"><span class="stat-icon">✦</span><div><b>${state.xp}</b><small>XP earned</small></div></div><div class="stat"><span class="stat-icon">◷</span><div><b>${state.days.length} <span style="font-size:13px">${state.days.length===1?'day':'days'}</span></b><small>Days practiced</small></div></div><div class="stat"><span class="stat-icon">✓</span><div><b>${mastered}<span style="font-size:13px;color:#8b9485"> / ${questions.length}</span></b><small>Skills reinforced</small></div></div></div>`}
function render(){document.body.dataset.practice='false';document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(view==='learn'){
app.innerHTML=`<div class="scenario-heading"><h1>Scenarios.</h1><button class="secondary" id="daily">Mixed practice</button></div><div class="cards scenario-cards">${topics.map(t=>`<article class="card"><div class="card-body"><h2>${t.title}</h2><p>${t.desc}</p></div><div class="scenario-actions"><button data-topic="${t.id}">Dialogue</button><button data-quiz="${t.id}">Practice →</button></div></article>`).join('')}</div>`;
document.querySelector('#daily').onclick=()=>start('all');app.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>dialogue(b.dataset.topic));app.querySelectorAll('[data-quiz]').forEach(b=>b.onclick=()=>start(b.dataset.quiz));
}else if(view==='dialogues'){app.innerHTML='<h1>Dialogues.</h1>';topics.forEach(t=>{let box=document.createElement('div');box.className='phrase';box.innerHTML=`<div><span class="eyebrow">${t.place}</span><h3>${t.title}</h3><p>${t.desc}</p></div>`;let b=document.createElement('button');b.className='secondary';b.textContent='Open →';b.onclick=()=>dialogue(t.id);box.append(b);app.append(box)})}else if(view==='vocabulary'){VocabularyTrainer.render(app,{speak,stop:()=>{if('speechSynthesis'in window)speechSynthesis.cancel();},onPractice:recordVocabularyPractice});}else if(view==='phrases'){app.innerHTML='<h1>Phrases.</h1><input class="search" aria-label="Search phrases" placeholder="Search French or English…"><div class="tabs">'+[['all','All phrases'],['essentials','Lifesavers'],...topics.map(t=>[t.id,t.title])].map(([id,s])=>`<button class="tab ${filter===id?'active':''}" data-filter="${id}">${s}</button>`).join('')+'</div><div id="phrases"></div><p class="metrics">Pronunciation spellings are approximate guides for English speakers. Listen for the French sounds.</p>';app.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});app.querySelector('input').oninput=phrases;phrases()}else{let vals=Object.values(state.answers),attempts=vals.reduce((n,a)=>n+a.attempts,0),right=vals.reduce((n,a)=>n+a.right,0);app.innerHTML=`<h1>Progress.</h1>${stats()}${vocabularyProgressCard()}<div class="section-heading"><h2>Your practical French</h2><span>${attempts?Math.round(right/attempts*100):0}% ANSWER ACCURACY</span></div>${topics.map(t=>{let q=questions.filter(q=>q.topic===t.id),n=q.filter(q=>(state.answers[q.id]?.right||0)>=2).length;return `<div class="bubble"><strong>${t.icon} ${t.title}</strong><div class="progressbar"><div style="width:${n/q.length*100}%"></div></div><span class="metrics">${n}/${q.length} skills answered correctly at least twice</span></div>`}).join('')}<div class="tip"><div><button class="primary" id="review">Practice my weakest skills →</button></div></div><p class="metrics">${attempts} answers checked · ${state.complete.length} scenarios practiced. Synced when online. Active rounds stay on this device.</p><button class="secondary" id="reset">Reset progress</button>`;document.querySelector('#review').onclick=()=>start('all');const reviewVocabulary=document.querySelector('#review-vocabulary');if(reviewVocabulary)reviewVocabulary.onclick=()=>{const due=VocabularyTrainer.summary().due;view='vocabulary';render();if(due>0)VocabularyTrainer.reviewDue();else VocabularyTrainer.reviewKnown();};document.querySelector('#reset').onclick=()=>{if(confirm('Reset learning progress on all synced devices? Personal word pairs stay saved.')){state={xp:0,answers:{},days:[],complete:[],day:1};VocabularyTrainer.resetProgress();save();window.LearningSync?.record('reset',{});render()}}}}
function phrases(){let query=(app.querySelector('input').value||'').toLowerCase();let list=[...essentials.map(p=>({p,topic:'essentials'})),...topics.flatMap(t=>[...t.phrases,...t.dialog.filter(l=>l[0]==='You').map(l=>l.slice(1))].map(p=>({p,topic:t.id})))].filter(x=>(filter==='all'||x.topic===filter)&&x.p.join(' ').toLowerCase().includes(query));const target=document.querySelector('#phrases');target.innerHTML='';if(!list.length)target.innerHTML='<p class="empty">No phrases found. Try “espresso”, “train”, or “hello”.</p>';list.forEach(({p})=>{let row=document.createElement('div');row.className='phrase';const div=document.createElement('div');let h=document.createElement('h3');h.lang='fr';h.textContent=p[0];div.append(h);p.slice(1).forEach(s=>{let e=document.createElement('p');e.textContent=s;div.append(e)});row.append(div,audio(p[0]));target.append(row)})}
function dialogue(id){let t=topics.find(t=>t.id===id);content.innerHTML=`<div class="eyebrow">${t.place} · LISTEN & LEARN</div><h2>${t.title}</h2>`;t.dialog.forEach(([role,fr,en,pron])=>{let b=document.createElement('div');b.className='bubble '+(role==='You'?'you':'');b.innerHTML=`<small>${role.toUpperCase()}</small><p lang="fr">${fr}</p><p class="translation">${en}</p><p class="phonetic">${pron}</p>`;let row=document.createElement('div');row.className='audio-row';row.append(audio(fr),audio(fr,true));b.append(row);content.append(b)});let note=document.createElement('p');note.className='metrics';note.textContent='Pronunciation hints are approximate. French audio uses your browser’s available voice. For introductions, replace Alex with your own name.';let b=document.createElement('button');b.className='primary';b.textContent='Try the practice →';b.onclick=()=>start(id);content.append(note,b);openLesson()}
function start(topic){session=questions.filter(q=>topic==='all'||q.topic===topic).map((q,i)=>({q,i,s:((state.answers[q.id]?.right||0)-2*(state.answers[q.id]?.miss||0))})).sort((a,b)=>a.s-b.s||a.i-b.i).slice(0,4).map(x=>x.q);qi=0;sessionCorrect=0;showQ();openLesson()}
function norm(s){return s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[’']/g,' ').replace(/[^a-z0-9 ]/g,'').replace(/\s+/g,' ').trim()}
const acceptedVariants = {
  hello:['Bonjour','Bonjour madame','Bonjour monsieur'],
  station:['Où se trouve la gare ?','Où est la gare, s’il vous plaît ?','Où se trouve la gare, s’il vous plaît ?'],
  ticket:['Je voudrais un billet pour Angers, s’il vous plaît.','Un billet pour Angers, s’il vous plaît.'],
  coffee:['Je voudrais un café, s’il vous plaît.','Je voudrais un café.'],
  here:['Sur place.','Sur place, s’il vous plaît.'],
  bill:['Je voudrais l’addition, s’il vous plaît.','Puis-je avoir l’addition, s’il vous plaît ?'],
  water:['Je voudrais une carafe d’eau, s’il vous plaît.','Une carafe d’eau.'],
  repeat:['Pouvez-vous répéter plus lentement, s’il vous plaît ?','Pourriez-vous répéter plus lentement ?'],
  talk:['Votre présentation était très intéressante, merci.','Votre présentation était intéressante.'],
  english:['Est-ce que vous parlez anglais ?','Parlez-vous anglais ?','Vous parlez anglais, s’il vous plaît ?']
};
Object.assign(acceptedVariants,{
  'hotel-booking':['J’ai une réservation au nom de Martin.','Une réservation au nom de Martin, s’il vous plaît.'],
  'hotel-breakfast':['À quelle heure est le petit déjeuner ?','À quelle heure est le petit-déjeuner, s’il vous plaît ?','À quelle heure est le petit déjeuner, s’il vous plaît ?'],
  'hotel-wifi':['Quel est le mot de passe du Wi-Fi, s’il vous plaît ?','Je peux avoir le mot de passe du Wi-Fi ?'],
  'hotel-checkout':['À quelle heure dois-je quitter la chambre ?','À quelle heure est le départ ?'],
  'tram-stop':['Où se trouve l’arrêt de tram ?','Où est l’arrêt de tram, s’il vous plaît ?'],
  'tram-line':['Quelle ligne dois-je prendre, s’il vous plaît ?','Quelle ligne faut-il prendre ?'],
  'tram-time':['À quelle heure part le prochain tram, s’il vous plaît ?','Quand part le prochain tram ?'],
  'tram-validate':['Comment valider mon billet, s’il vous plaît ?','Comment est-ce que je valide mon billet ?'],
  'bakery-bread':['Je voudrais une baguette.','Je voudrais une baguette, s’il vous plaît.'],
  'bakery-quantity':['Je voudrais deux croissants.','Je voudrais deux croissants, s’il vous plaît.'],
  'bakery-price':['Combien ça coûte, s’il vous plaît ?','C’est combien ?'],
  'bakery-card':['Est-ce que je peux payer par carte ?','Puis-je payer par carte ?'],
  'restaurant-menu':['Je peux avoir la carte ?','La carte, s’il vous plaît.','Puis-je avoir la carte, s’il vous plaît ?'],
  'restaurant-vegetarian':['Est-ce que vous avez un plat végétarien ?','Avez-vous un plat végétarien ?'],
  'restaurant-allergy':['Je suis allergique aux cacahuètes.'],
  'restaurant-finished':['J’ai fini, merci.','Oui, j’ai terminé, merci.'],
  'registration-badge':['Bonjour, je viens chercher mon badge.','Je suis ici pour récupérer mon badge.'],
  'registration-programme':['Le programme, s’il vous plaît.','Je peux avoir le programme, s’il vous plaît ?','Puis-je avoir le programme ?'],
  'registration-room':['Où est la salle de conférence, s’il vous plaît ?','Où se trouve la salle de conférence ?'],
  'registration-start':['Quand commence la séance ?','À quelle heure commence la séance, s’il vous plaît ?'],
  'networking-question':['Est-ce que je peux vous poser une question ?','Puis-je vous poser une question ?'],
  'networking-contact':['Est-ce qu’on peut échanger nos adresses e-mail ?','Pouvons-nous échanger nos adresses e-mail ?'],
  'networking-thanks':['Merci beaucoup pour votre temps.']
});
function acceptsAnswer(q,value) {
  const normalized=norm(value);
  if (q.id==='name' && /^je m appelle [a-z][a-z ]{0,59}$/.test(normalized)) return true;
  return [q.a[q.correct],...(acceptedVariants[q.id]||[])].some(s=>norm(s)===normalized);
}
function focusLesson() {
  const heading=content.querySelector('h2');
  if (heading) {heading.id='lesson-title';heading.tabIndex=-1;modal.setAttribute('aria-labelledby',heading.id);heading.focus();}
}
function openLesson() {if(!modal.open) modal.showModal();focusLesson();}
function showQ(){answered=false;let q=session[qi],hard=(state.answers[q.id]?.streak||0)>=2&&q.correct!==undefined&&q.id!=='right';content.innerHTML=`<div class="eyebrow">PRACTICE · ${qi+1} OF ${session.length}</div><div class="progressbar"><div style="width:${qi/session.length*100}%"></div></div><h2>${q.q}</h2><p class="sub">${hard?'Recall the practiced phrase, or use another accepted way to say it. Accents and punctuation are optional.':'Choose the phrase you would use.'}</p><div class="options"></div><div id="feedback" aria-live="polite"></div>`;let target=content.querySelector('.options');if(hard){let input=document.createElement('input');input.className='search';input.placeholder='Type the French phrase…';input.setAttribute('aria-label','Your French answer');input.lang='fr';input.autocapitalize='sentences';input.setAttribute('autocorrect','off');input.spellcheck=false;let b=document.createElement('button');b.className='primary';b.textContent='Check answer';let check=()=>{if(!input.value.trim()){toast('Write your answer first.');return}b.disabled=true;input.disabled=true;answer(acceptsAnswer(q,input.value),q)};b.onclick=check;input.onkeydown=e=>{if(e.key==='Enter'&&!answered)check()};target.append(input,b)}else q.a.forEach((s,i)=>{let b=document.createElement('button');b.className='option';b.textContent=s;b.onclick=()=>{if(answered)return;target.querySelectorAll('button').forEach((x,j)=>{x.disabled=true;if(j===q.correct)x.classList.add('correct')});if(i!==q.correct)b.classList.add('wrong');answer(i===q.correct,q)};target.append(b)});if(modal.open)focusLesson()}
function answer(ok,q){if(answered)return;answered=true;let a=state.answers[q.id]||{right:0,miss:0,attempts:0};a.attempts++;if(ok){a.right++;a.streak=Math.min(2,(a.streak||0)+1);state.xp+=10;sessionCorrect++}else {a.miss++;a.streak=0}state.answers[q.id]=a;let day=new Date().toLocaleDateString('en-CA');if(!state.days.includes(day))state.days.push(day);save();window.LearningSync?.record('app.scenario',{questionId:q.id,ok,day});let f=document.querySelector('#feedback');f.innerHTML=`<div class="feedback"><strong>${ok?'Très bien ! ✓':'A useful one to remember'}</strong><br><span lang="fr">${q.a[q.correct]}</span><br>${q.why}${ok?'':'<br>This skill will be prioritized in future practice.'}</div>`;let row=document.createElement('div');row.className='audio-row';row.append(audio(q.a[q.correct]));if(q.id==='right')row.replaceChildren(audio('C’est à droite.'));let b=document.createElement('button');b.className='primary';b.textContent=qi<session.length-1?'Next question →':'See my progress →';b.onclick=()=>{qi++;if(qi<session.length)showQ();else finish()};f.append(row,document.createElement('br'),b)}
function finish(){const ids=[...new Set(session.map(q=>q.topic))],completed=[];ids.forEach(id=>{if(!state.complete.includes(id)&&session.filter(q=>q.topic===id).length===4){state.complete.push(id);completed.push(id);}});save();completed.forEach(id=>window.LearningSync?.record('app.complete',{topic:id}));content.innerHTML=`<h2>Done.</h2><p>${sessionCorrect} / ${session.length} correct</p><button class="primary" id="done">Scenarios</button>`;document.querySelector('#done').onclick=()=>{modal.close();view='learn';render()};render();focusLesson();}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{if('speechSynthesis'in window)speechSynthesis.cancel();view=b.dataset.view;render()});document.querySelector('#close').onclick=()=>{modal.close();if('speechSynthesis'in window)speechSynthesis.cancel();render()};modal.addEventListener('close',()=>{if('speechSynthesis'in window)speechSynthesis.cancel();render()});render();

function recordVocabularyPractice(xp){state.xp+=xp;const date=new Date().toLocaleDateString('en-CA');if(!state.days.includes(date))state.days.push(date);save();}
function vocabularyProgressCard(){const s=VocabularyTrainer.summary();const review=s.due>0?`Review ${s.due} due ${s.due===1?'word':'words'}`:s.practiced>0?'Review learned words':'';return `<div class="bubble"><strong>Your vocabulary</strong><p class="metrics">${s.learned} of ${s.total} well-known words · ${s.due} ready to review · ${s.new} new words</p>${review?`<button type="button" class="secondary" id="review-vocabulary">${review}</button>`:''}</div>`;}

addEventListener('angers:sync-applied',event=>{state=restoreProgress();const invalid=VocabularyTrainer.acceptSync?.(event.detail.vocab);if(view==='progress'||(invalid&&view==='vocabulary'))render();});

addEventListener('angers:sync-profile-changed',()=>{document.querySelector('#app').inert=true;document.querySelector('nav').inert=true;setTimeout(()=>location.reload(),0);});

const syncTools=document.querySelector('#sync-tools');syncTools?.addEventListener('toggle',()=>{if(syncTools.open)document.querySelector('#app-tools').open=true;});
addEventListener('angers:sync-error',event=>{let notice=document.querySelector('#sync-critical');if(!notice){notice=document.createElement('div');notice.id='sync-critical';notice.className='vocab-warning';notice.setAttribute('role','alert');document.querySelector('#app').prepend(notice);}notice.textContent=event.detail||'Sync storage is unavailable. Export a backup before closing.';const button=document.createElement('button');button.className='secondary';button.textContent='Export backup';button.onclick=()=>window.LearningSync?.exportBackup();notice.append(document.createElement('br'),button);});

function getLocalLearningSnapshot(){const app=structuredClone(state);app.days=app.days.filter(day=>/^\d{4}-\d{2}-\d{2}$/.test(day)&&!Number.isNaN(Date.parse(day)));return {app,vocab:VocabularyTrainer.snapshot()};}
